window.QB=window.QB||{};QB.ae={"name": "Animal Experiments (amphibian)", "vol": "Practicals · frog nerve–muscle & heart · simulated in CBME", "topics": ["Apparatus for amphibian experiments", "Simple muscle twitch (gastrocnemius–sciatic preparation)", "Effect of temperature on muscle twitch", "Effect of load: free-load and after-load (work done)", "Effect of two successive stimuli (summation)", "Genesis of tetanus", "Fatigue in skeletal muscle", "Velocity of nerve impulse (frog sciatic nerve)", "Normal cardiogram of the frog heart", "All-or-none law and staircase phenomenon (frog heart)", "Refractory period, extrasystole and compensatory pause", "Stannius ligatures", "Effect of temperature on the frog heart", "Vagal stimulation and vagal escape", "Effects of drugs and ions on the frog heart", "Perfusion of the isolated frog heart", "Simulations and CAL in CBME (replacing live animals)"], "notes": [["Apparatus for amphibian experiments", "Aim: To identify and know the uses of the apparatus used for recording frog muscle and heart experiments.", "", ["Why is the break shock stronger than the make shock?", "What is the use of Neef's hammer?", "What is the function of the Lucas moist chamber?", "Why is a tuning fork of 100 Hz used?"], {"kp": ["Kymograph = recording drum; levers write on it.", "Induction coil: break shock > make shock.", "Neef's hammer → faradic (tetanizing) current.", "Lucas chamber keeps the preparation moist.", "100 Hz tuning fork: each wave 0.01 s."], "ex": "Viva/practical record: Aim → apparatus → procedure → tracing (labelled) → observations → explanation → precautions.", "ae": {"aim": "To identify and know the uses of the apparatus used for recording frog muscle and heart experiments.", "app": ["Kymograph (Sherrington–Starling type): an electrically driven revolving drum covered with smoked (or glazed) paper on which writing levers record; speed can be changed by gears.", "Simple muscle lever / Starling's heart lever: a light lever with a writing point; magnifies the contraction. The muscle lever has an after-load screw and a weight hook.", "Induction coil (Du Bois-Reymond type): primary coil (connected to battery and key) and secondary coil (connected to electrodes). Moving the secondary coil closer to the primary increases stimulus strength. Gives single make and break induction shocks; the break shock is stronger.", "Neef's hammer: an automatic interrupter in the primary circuit that makes and breaks the current repeatedly, giving a faradic (tetanizing) current from the secondary coil.", "Keys: simple (tapping) key in the primary circuit; Du Bois-Reymond short-circuiting key in the secondary circuit.", "Lucas moist chamber: a chamber in which the nerve–muscle preparation is mounted; it keeps the preparation moist (with Ringer's solution) and has built-in electrodes.", "Electrodes, signal (stimulus) marker, time marker or tuning fork (100 Hz – each wave = 0.01 s), myograph stand, frog board, pithing needle, serrefine, Ringer's solution.", "Modern alternative: electronic stimulator with a transducer and computer data-acquisition system, or simulation software."], "steps": ["Learn to set up the drum, adjust the lever so that it writes tangentially with minimal friction.", "Connect battery → key → primary coil; secondary coil → short-circuiting key → electrodes.", "Set the drum speed: fast for a simple twitch, slow for fatigue, tetanus and heart."], "tr": "No tracing; the instruments produce the records used in all other experiments. The time trace and the stimulus marker are written below the main tracing.", "obs": ["Break shock produces a response at a lower coil strength than the make shock.", "Closing the short-circuiting key cuts off current to the tissue."], "expl": "Break shock is stronger than make shock because at make, self-induction in the primary coil opposes the rise of current, so the rise is slow; at break the current falls abruptly, inducing a larger, sharper current in the secondary coil.", "prec": ["Writing point should touch the drum lightly and tangentially.", "Keep the short-circuiting key closed while not stimulating.", "Keep the tissue moist with Ringer's solution."], "viva": [["Why is the break shock stronger than the make shock?", "At make, self-induction opposes the rise of current in the primary coil, so the induced current is slower and weaker; at break the current stops abruptly and the induced current is stronger."], ["What is the use of Neef's hammer?", "It automatically makes and breaks the primary circuit repeatedly to give a faradic (repetitive) current used to produce tetanus or to stimulate the vagus."], ["What is the function of the Lucas moist chamber?", "It keeps the nerve–muscle preparation moist and at a steady state, and carries electrodes for stimulation."], ["Why is a tuning fork of 100 Hz used?", "It records a time trace in which each complete wave equals 0.01 s, so periods of the twitch can be measured."]], "cal": "CBME note: live frog experiments are no longer done; these are taught with computer simulations, computer-assisted learning (CAL) modules or recorded demonstrations. Learn the tracings and their explanation."}}], ["Simple muscle twitch (gastrocnemius–sciatic preparation)", "Aim: To record a simple muscle twitch of the frog gastrocnemius–sciatic preparation and to study its periods.", "", ["What are the periods of a simple muscle twitch?", "What contributes to the latent period?", "Why is relaxation longer than contraction?", "Why is a fast drum speed used?", "Why is a frog used and why Ringer's solution?"], {"kp": ["Gastrocnemius–sciatic preparation; single break shock; fast drum.", "LP ≈ 0.01 s, CP ≈ 0.04 s, RP ≈ 0.05 s; total ≈ 0.1 s.", "Latent period includes apparatus latency."], "ex": "Viva/practical record: Aim → apparatus → procedure → tracing (labelled) → observations → explanation → precautions.", "ae": {"aim": "To record a simple muscle twitch of the frog gastrocnemius–sciatic preparation and to study its periods.", "app": ["Kymograph (fast speed)", "Muscle lever in Lucas moist chamber or on myograph stand", "Induction coil, key, electrodes", "Tuning fork (100 Hz) / time marker, stimulus marker", "Frog, pithing needle, dissection instruments, Ringer's solution"], "steps": ["Pith the frog (destroy brain and spinal cord) and dissect out the gastrocnemius muscle with the sciatic nerve attached (gastrocnemius–sciatic preparation).", "Fix the femur/knee end in the clamp and tie the tendo calcaneus (Achilles tendon) to the muscle lever.", "Place the nerve on the electrodes; keep the preparation moist with Ringer's solution.", "Run the drum at high speed and give a single break induction shock; record the twitch.", "Without moving the drum's starting position, record the time trace (tuning fork) and mark the point of stimulation."], "tr": "A small flat segment after the stimulus mark (latent period), then a steep rising limb to a peak (contraction period) and a slower descending limb back to the baseline (relaxation period). The descending limb may show small after-oscillations due to the inertia of the lever.", "obs": ["Latent period ≈ 0.01 s", "Contraction period ≈ 0.04 s", "Relaxation period ≈ 0.05 s", "Total duration ≈ 0.1 s (values for frog muscle at room temperature, as given in practical manuals)"], "expl": "Latent period is the time between application of the stimulus and the start of contraction. It includes the time for conduction along the nerve, neuromuscular transmission, the muscle action potential and excitation–contraction coupling, plus the apparatus latency (inertia and friction of the lever, slack in the thread). Contraction is due to cross-bridge cycling after Ca²⁺ release from the sarcoplasmic reticulum; relaxation needs active Ca²⁺ re-uptake, so it is longer than contraction.", "prec": ["Do not stretch or injure the nerve; handle it with a glass hook.", "Keep the preparation moist with Ringer's solution.", "Lever should be horizontal and write tangentially with minimal friction.", "Use a single break shock of just-maximal strength.", "Record the time trace without changing the starting position of the drum."], "viva": [["What are the periods of a simple muscle twitch?", "Latent period (~0.01 s), contraction period (~0.04 s) and relaxation period (~0.05 s) in frog gastrocnemius."], ["What contributes to the latent period?", "Nerve conduction, neuromuscular delay, muscle action potential and excitation–contraction coupling, plus apparatus latency (lever inertia, slack)."], ["Why is relaxation longer than contraction?", "Relaxation requires active pumping of Ca²⁺ back into the sarcoplasmic reticulum (SERCA, uses ATP) and passive return of the elastic elements."], ["Why is a fast drum speed used?", "To spread out the short twitch (about 0.1 s) so the periods can be measured."], ["Why is a frog used and why Ringer's solution?", "Frog tissues survive at room temperature for long periods; Ringer's solution is isotonic for amphibian tissues and supplies Na⁺, K⁺ and Ca²⁺."]], "cal": "CBME note: live frog experiments are no longer done; these are taught with computer simulations, computer-assisted learning (CAL) modules or recorded demonstrations. Learn the tracings and their explanation."}}], ["Effect of temperature on muscle twitch", "Aim: To study the effect of warm and cold Ringer's solution on the simple muscle twitch.", "", ["What is heat rigor?", "Why does warming shorten the periods?", "What happens to the latent period in cold?"], {"kp": ["Warm → shorter periods, taller curve.", "Cold → longer periods, shorter curve.", "Excess heat → heat rigor (protein coagulation)."], "ex": "Viva/practical record: Aim → apparatus → procedure → tracing (labelled) → observations → explanation → precautions.", "ae": {"aim": "To study the effect of warm and cold Ringer's solution on the simple muscle twitch.", "app": ["As for simple muscle twitch", "Ringer's solution at room temperature, warm (about 30–35 °C) and ice-cold"], "steps": ["Record a normal twitch at room temperature (fast drum).", "Pour cold Ringer's solution over the muscle; after a short time record a twitch from the same starting point.", "Restore to room temperature, then pour warm Ringer's and record another twitch.", "Record the time trace and label each curve."], "tr": "Three superimposed curves starting from the same stimulus point: the warm curve starts earliest, rises and falls quickly and is the shortest in duration; the cold curve starts late, is broad and prolonged; the room-temperature curve lies between them.", "obs": ["Warm: latent, contraction and relaxation periods all shortened; height of contraction increased (within physiological limits).", "Cold: all periods prolonged; height of contraction reduced.", "Very high temperature (above about 40 °C in frog muscle) causes heat rigor – irreversible shortening due to coagulation of muscle proteins."], "expl": "Chemical reactions (enzyme activity, myosin ATPase, Ca²⁺ release and re-uptake) and the viscosity of the muscle change with temperature. Warmth speeds reactions and lowers viscosity, so all periods shorten; cold slows them.", "prec": ["Pour equal volumes of Ringer's; allow time for the temperature to act.", "Do not overheat (risk of heat rigor).", "Record all curves from the same starting point on the drum."], "viva": [["What is heat rigor?", "Irreversible shortening of muscle at high temperature due to coagulation of muscle proteins (myosin)."], ["Why does warming shorten the periods?", "It increases the rate of chemical and enzymatic reactions and decreases viscosity of the muscle."], ["What happens to the latent period in cold?", "It is prolonged."]], "cal": "CBME note: live frog experiments are no longer done; these are taught with computer simulations, computer-assisted learning (CAL) modules or recorded demonstrations. Learn the tracings and their explanation."}}], ["Effect of load: free-load and after-load (work done)", "Aim: To study the effect of increasing load on muscle contraction with free-loading and after-loading, and to calculate the work done.", "", ["Differentiate free-load and after-load.", "Why is work done greater in free-load?", "When is work done zero?", "How do you calculate work done?"], {"kp": ["Free-load: muscle pre-stretched; height ↑ then ↓.", "After-load: initial length constant; height ↓ progressively.", "Work = W × h; maximal at optimum load; more with free-load."], "ex": "Viva/practical record: Aim → apparatus → procedure → tracing (labelled) → observations → explanation → precautions.", "ae": {"aim": "To study the effect of increasing load on muscle contraction with free-loading and after-loading, and to calculate the work done.", "app": ["As for simple muscle twitch, with a muscle lever having a weight hook and after-load screw", "Weights (e.g. 10 g, 20 g, 30 g …)", "Slow or stationary drum (contractions recorded as vertical lines side by side)"], "steps": ["Free-load: hang a weight from the lever without support so the muscle is stretched before it contracts. Give a maximal shock and record a contraction; move the drum by hand a little.", "Repeat with progressively greater weights until the muscle cannot lift the load.", "After-load: adjust the after-load screw so the lever rests on it; the weight is not borne by the muscle at rest (initial length constant).", "Repeat with the same series of weights and record.", "Measure the height of each contraction, correct for lever magnification, and calculate work done = load × height lifted."], "tr": "A series of vertical lines. Free-load: height first increases with the first few weights, then decreases. After-load: height decreases progressively from the first weight. For the same weight the free-loaded contraction is taller.", "obs": ["Free-load: the height of contraction increases up to an optimum load and then falls.", "After-load: the height decreases steadily as load increases.", "Work done rises from zero (no load), reaches a maximum at an intermediate (optimum) load and falls to zero when the load is too heavy to lift.", "Work done is greater with free-loading than with after-loading for the same weight."], "expl": "In free-loading the weight stretches the muscle before contraction, increasing its initial length; within limits, greater initial length gives a stronger contraction (length–tension relationship, the skeletal-muscle counterpart of the Frank–Starling law). In after-loading the initial length is not increased, so this advantage is lost. External work = force × distance; it is zero when the load is zero and when the muscle cannot lift the load, so it is maximal at an intermediate load.", "prec": ["Use maximal stimulus throughout.", "Give rest between contractions to avoid fatigue.", "Correct the height for lever magnification before calculating work.", "Add weights gently."], "viva": [["Differentiate free-load and after-load.", "In free-loading the weight acts on the muscle before contraction and stretches it (initial length increases); in after-loading the weight is supported so the muscle bears it only after it begins to contract (initial length unchanged)."], ["Why is work done greater in free-load?", "Because the pre-stretch increases initial length and hence force of contraction (length–tension relationship)."], ["When is work done zero?", "When there is no load, and when the load is too heavy to be lifted."], ["How do you calculate work done?", "Work = load (weight) × actual height lifted (recorded height ÷ lever magnification)."]], "cal": "CBME note: live frog experiments are no longer done; these are taught with computer simulations, computer-assisted learning (CAL) modules or recorded demonstrations. Learn the tracings and their explanation."}}], ["Effect of two successive stimuli (summation)", "Aim: To study the effect of two successive stimuli applied at different intervals on skeletal muscle.", "", ["What is the refractory period of skeletal muscle?", "Why can skeletal muscle summate but cardiac muscle cannot?", "What is the beneficial effect?"], {"kp": ["Skeletal muscle RP ≈ 0.005 s – shorter than contraction.", "Second stimulus during contraction/relaxation → summation.", "After relaxation → 2 twitches; beneficial effect."], "ex": "Viva/practical record: Aim → apparatus → procedure → tracing (labelled) → observations → explanation → precautions.", "ae": {"aim": "To study the effect of two successive stimuli applied at different intervals on skeletal muscle.", "app": ["As for simple muscle twitch", "Two keys or a stimulator giving paired stimuli at adjustable intervals (classically, a contact/striker on the drum)"], "steps": ["Record a single twitch with a maximal stimulus (fast drum).", "Apply two stimuli of equal strength with the second falling: (a) very soon after the first (within the refractory period), (b) during the contraction period, (c) during the relaxation period, (d) after complete relaxation.", "Record each pair from the same starting point and mark the stimuli."], "tr": "(a) a single curve identical to a simple twitch; (b) a single curve taller than a simple twitch; (c) a second curve rising from the falling limb of the first, reaching a greater height; (d) two separate twitches, the second may be slightly taller.", "obs": ["Second stimulus in the refractory period (about 0.005 s in skeletal muscle): no extra response.", "During contraction: a larger single contraction (superposition/summation).", "During relaxation: a second contraction arises from the partially relaxed state and is summed.", "After complete relaxation: two separate twitches; the second may be slightly higher (beneficial effect)."], "expl": "Skeletal muscle has a very short refractory period, which ends long before the mechanical response finishes. So a second stimulus can produce a second contraction before the first has ended, and the two mechanical responses add up (wave/temporal summation). The extra Ca²⁺ release adds to that still present. The slightly greater second response after full relaxation (beneficial effect) is attributed to increased Ca²⁺ availability and warming.", "prec": ["Both stimuli must be of the same (maximal) strength.", "Avoid fatigue by resting between recordings.", "Mark the instant of each stimulus."], "viva": [["What is the refractory period of skeletal muscle?", "Very short – about 0.005 s in frog skeletal muscle (shorter than the contraction period)."], ["Why can skeletal muscle summate but cardiac muscle cannot?", "Skeletal muscle's refractory period ends early in the contraction; cardiac muscle's absolute refractory period lasts throughout systole."], ["What is the beneficial effect?", "The second of two twitches given after complete relaxation is slightly greater, due to increased Ca²⁺ availability, warming and lowered viscosity."]], "cal": "CBME note: live frog experiments are no longer done; these are taught with computer simulations, computer-assisted learning (CAL) modules or recorded demonstrations. Learn the tracings and their explanation."}}], ["Genesis of tetanus", "Aim: To study the effect of increasing frequency of stimulation on skeletal muscle (genesis of tetanus).", "", ["Define tetanus.", "Difference between complete and incomplete tetanus?", "Why cannot cardiac muscle be tetanized?", "Why is tetanic tension greater than a twitch?"], {"kp": ["↑ frequency: twitches → clonus → complete tetanus.", "Tetanic tension several × twitch.", "Heart cannot be tetanized (long ARP)."], "ex": "Viva/practical record: Aim → apparatus → procedure → tracing (labelled) → observations → explanation → precautions.", "ae": {"aim": "To study the effect of increasing frequency of stimulation on skeletal muscle (genesis of tetanus).", "app": ["As for simple muscle twitch", "Induction coil with Neef's hammer or electronic stimulator with variable frequency", "Slow-moving drum"], "steps": ["Stimulate the nerve (maximal strength) at a low frequency (e.g. 1 per second) and record.", "Increase the frequency step by step and record each series.", "Note separate twitches, then incomplete tetanus (clonus), then complete tetanus."], "tr": "Low frequency: separate twitches. Moderate frequency: a wavy plateau with partial relaxation between contractions – incomplete tetanus (clonus). High frequency: a smooth sustained plateau with no relaxation – complete tetanus, much higher than a single twitch. The first few contractions may rise step-wise.", "obs": ["Low frequency – separate twitches (may show staircase).", "When each stimulus falls in the relaxation phase of the previous one – incomplete tetanus.", "When each stimulus falls in the contraction phase – complete tetanus (smooth fused contraction).", "Tetanic tension is several times greater than that of a single twitch."], "expl": "Because the refractory period of skeletal muscle is very short, repeated stimuli summate (temporal summation). Continued Ca²⁺ release keeps Ca²⁺ high in the sarcoplasm, so cross-bridges keep cycling and the series elastic component is fully stretched, producing a fused, stronger contraction. The minimum frequency for complete tetanus is called the fusion frequency; it depends on the twitch duration (lower in slow muscles and in cold).", "prec": ["Use maximal stimulus strength.", "Stimulate for only a few seconds to avoid fatigue.", "Allow rest between series."], "viva": [["Define tetanus.", "A sustained, fused contraction of skeletal muscle produced by repetitive stimulation at high frequency so that there is no relaxation between stimuli."], ["Difference between complete and incomplete tetanus?", "Incomplete (clonus): stimuli fall in the relaxation phase – wavy plateau; complete: stimuli fall in the contraction phase – smooth plateau."], ["Why cannot cardiac muscle be tetanized?", "Its absolute refractory period lasts as long as the contraction (systole)."], ["Why is tetanic tension greater than a twitch?", "Sustained high Ca²⁺ allows full cross-bridge activation and the series elastic elements are fully stretched."]], "cal": "CBME note: live frog experiments are no longer done; these are taught with computer simulations, computer-assisted learning (CAL) modules or recorded demonstrations. Learn the tracings and their explanation."}}], ["Fatigue in skeletal muscle", "Aim: To study the phenomenon of fatigue and its site in a nerve–muscle preparation.", "", ["Which site fatigues first in a nerve–muscle preparation?", "How do you prove it?", "Is nerve fatigable?", "What is contracture?"], {"kp": ["Height ↓, periods ↑ (relaxation most), contracture.", "NMJ fatigues first; nerve practically unfatigable."], "ex": "Viva/practical record: Aim → apparatus → procedure → tracing (labelled) → observations → explanation → precautions.", "ae": {"aim": "To study the phenomenon of fatigue and its site in a nerve–muscle preparation.", "app": ["As for simple muscle twitch", "Stimulator giving regular stimuli (e.g. one per second)", "Slow-moving drum (or move the drum a little between contractions)"], "steps": ["Stimulate the nerve with maximal shocks at regular intervals and record successive contractions until the response becomes very small or stops.", "Now stimulate the muscle directly: it contracts again.", "Optionally, record selected contractions on a fast drum to compare the periods of the first and fatigued contractions."], "tr": "A series of contractions whose heights first may rise slightly (staircase), then fall progressively. The baseline rises because relaxation becomes incomplete (contracture). Superimposed fast-drum curves show the fatigued twitch is lower and broader.", "obs": ["Height of contraction decreases progressively.", "Latent period, contraction period and especially relaxation period are prolonged.", "Incomplete relaxation (contracture) – baseline rises.", "After indirect (nerve) stimulation fails, direct stimulation of the muscle still produces contraction."], "expl": "In a nerve–muscle preparation the neuromuscular junction fatigues first (depletion of acetylcholine), so the muscle still responds to direct stimulation; the nerve is practically unfatigable. In the muscle itself, fatigue is due to depletion of energy stores (ATP, creatine phosphate, glycogen) and accumulation of metabolites such as lactic acid and phosphate; slower Ca²⁺ re-uptake prolongs relaxation.", "prec": ["Keep the preparation moist.", "Use a constant, maximal stimulus.", "Note the time of stimuli."], "viva": [["Which site fatigues first in a nerve–muscle preparation?", "The neuromuscular junction."], ["How do you prove it?", "After the muscle stops responding to nerve stimulation, direct stimulation of the muscle still produces contraction."], ["Is nerve fatigable?", "Nerve fibre is practically unfatigable."], ["What is contracture?", "Incomplete relaxation of a fatigued muscle (baseline rises), due to slowed Ca²⁺ re-uptake and lack of ATP."]], "cal": "CBME note: live frog experiments are no longer done; these are taught with computer simulations, computer-assisted learning (CAL) modules or recorded demonstrations. Learn the tracings and their explanation."}}], ["Velocity of nerve impulse (frog sciatic nerve)", "Aim: To determine the velocity of conduction of the nerve impulse in the frog sciatic nerve.", "", ["Why is the difference in latent periods used?", "Who first measured nerve conduction velocity?", "What factors increase conduction velocity?", "How is nerve conduction velocity measured in humans?"], {"kp": ["Stimulate at 2 points; v = d ÷ Δ latent period.", "Frog sciatic ≈ 30 m/s at room temperature."], "ex": "Viva/practical record: Aim → apparatus → procedure → tracing (labelled) → observations → explanation → precautions.", "ae": {"aim": "To determine the velocity of conduction of the nerve impulse in the frog sciatic nerve.", "app": ["As for simple muscle twitch", "Two pairs of electrodes on the nerve: one near the muscle, one far from it", "Very fast drum (or pendulum/spring myograph); tuning fork for time trace"], "steps": ["Mount the gastrocnemius–sciatic preparation with a long length of sciatic nerve.", "Stimulate the nerve near the muscle with a maximal shock and record a twitch.", "Without moving the starting point, stimulate the nerve at a point far from the muscle and record a second twitch.", "Record the time trace; measure the distance between the two stimulation points."], "tr": "Two identical twitch curves that start from the same baseline; the curve from the distant point begins slightly later. The horizontal distance between the starting points of the two curves corresponds to the extra conduction time.", "obs": ["The latent period is longer when the far point is stimulated.", "Velocity = distance between the two points ÷ difference in latent periods.", "Frog sciatic nerve conducts at roughly 30 m/s at room temperature (Helmholtz first measured nerve conduction velocity in frog nerve in 1850, about 27 m/s)."], "expl": "The only difference between the two recordings is the extra length of nerve the impulse travels; all other components of the latent period are the same, so they cancel out in the subtraction.", "prec": ["Use a very fast drum to separate the curves.", "Both stimuli must be maximal and identical.", "Measure the distance between electrodes accurately.", "Keep the nerve moist; do not stretch it."], "viva": [["Why is the difference in latent periods used?", "The other components of the latent period (NMJ delay, E–C coupling, apparatus latency) are equal and cancel out."], ["Who first measured nerve conduction velocity?", "Hermann von Helmholtz (1850), using frog nerve–muscle preparation."], ["What factors increase conduction velocity?", "Larger fibre diameter, myelination and higher temperature."], ["How is nerve conduction velocity measured in humans?", "By nerve conduction studies – stimulating a nerve at two points and recording the muscle or nerve action potential."]], "cal": "CBME note: live frog experiments are no longer done; these are taught with computer simulations, computer-assisted learning (CAL) modules or recorded demonstrations. Learn the tracings and their explanation."}}], ["Normal cardiogram of the frog heart", "Aim: To record the normal contractions of the frog heart (cardiogram) and identify its features.", "", ["What is the pacemaker of the frog heart?", "How many chambers has the frog heart?", "What does the upstroke of the cardiogram represent?", "Why is the frog heart preferred for study?"], {"kp": ["Sinus venosus = pacemaker.", "Small wave (atrial systole) → large wave (ventricular systole) → diastole.", "Starling's heart lever, slow drum."], "ex": "Viva/practical record: Aim → apparatus → procedure → tracing (labelled) → observations → explanation → precautions.", "ae": {"aim": "To record the normal contractions of the frog heart (cardiogram) and identify its features.", "app": ["Kymograph (slow speed)", "Starling's heart lever", "Serrefine (heart clip) and thread", "Frog board, pithing needle, dissection instruments, Ringer's solution"], "steps": ["Pith the frog, lay it on its back and open the chest by cutting the sternum to expose the heart.", "Open the pericardium; identify sinus venosus (dorsal), two atria, single ventricle and truncus arteriosus.", "Attach a serrefine to the tip of the ventricle and connect it by thread to Starling's heart lever.", "Adjust the lever so it writes on a slowly moving drum; record a few beats with the time trace.", "Keep the heart moist with Ringer's solution."], "tr": "Regular waves: each beat shows a small rise due to atrial systole followed immediately by a larger, taller rise due to ventricular systole, then a descending limb (diastole) and a short pause (period of rest) at the baseline before the next beat. Upstroke = systole; downstroke = diastole.", "obs": ["Rhythmic, regular beats.", "Each cycle: atrial systole (small wave) → ventricular systole (large wave) → diastole → pause.", "The heart rate is slow compared with mammals and depends on temperature."], "expl": "The beat starts in the sinus venosus (pacemaker of the frog heart), spreads to the atria and then to the ventricle. The frog heart has three chambers (two atria and one ventricle) plus sinus venosus and truncus arteriosus. Counting the waves against the time trace gives the rate.", "prec": ["Do not injure the sinus venosus while exposing the heart.", "Keep the heart moist with Ringer's solution.", "Thread should be vertical and taut; lever horizontal.", "Use a slow drum."], "viva": [["What is the pacemaker of the frog heart?", "Sinus venosus."], ["How many chambers has the frog heart?", "Three: two atria and one ventricle (plus sinus venosus and truncus arteriosus)."], ["What does the upstroke of the cardiogram represent?", "Systole (atrial – small wave, ventricular – large wave)."], ["Why is the frog heart preferred for study?", "It continues beating at room temperature for long periods, is easily exposed and the sinus venosus is visible."]], "cal": "CBME note: live frog experiments are no longer done; these are taught with computer simulations, computer-assisted learning (CAL) modules or recorded demonstrations. Learn the tracings and their explanation."}}], ["All-or-none law and staircase phenomenon (frog heart)", "Aim: To demonstrate the all-or-none law and the staircase (Treppe) phenomenon in frog cardiac muscle.", "", ["Why does the whole ventricle obey the all-or-none law?", "Does whole skeletal muscle obey the all-or-none law?", "What is the staircase phenomenon?", "Why is a Stannius ligature used here?"], {"kp": ["Ventricle (syncytium) obeys all-or-none.", "Staircase: progressive ↑ in first contractions (Ca²⁺).", "Use quiescent ventricle (1st Stannius ligature)."], "ex": "Viva/practical record: Aim → apparatus → procedure → tracing (labelled) → observations → explanation → precautions.", "ae": {"aim": "To demonstrate the all-or-none law and the staircase (Treppe) phenomenon in frog cardiac muscle.", "app": ["As for normal cardiogram", "Induction coil, key, electrodes (single break shocks)", "A quiescent ventricle obtained by the first Stannius ligature"], "steps": ["Expose the heart and tie the first Stannius ligature (sinus venosus–atrial junction) so that the atria and ventricle stop.", "All-or-none: stimulate the ventricle with single break shocks of increasing strength (sub-threshold, threshold, supra-threshold) at sufficient intervals; record.", "Staircase: stimulate the quiescent ventricle with break shocks of the same strength at regular short intervals (e.g. every few seconds); record."], "tr": "All-or-none: no response to sub-threshold stimuli; at threshold a full contraction appears, and stronger stimuli give contractions of the same height. Staircase: a series of contractions, each of the first few slightly taller than the one before, like steps, then a constant height.", "obs": ["Sub-threshold stimulus – no contraction.", "Threshold and supra-threshold stimuli – maximal contractions of equal height (all-or-none).", "Repeated equal stimuli – first few contractions progressively increase in height (staircase/Treppe)."], "expl": "Cardiac muscle behaves as a functional syncytium: cells are connected by gap junctions in intercalated discs, so an impulse spreads to the whole ventricle and all fibres contract together; hence the whole ventricle obeys the all-or-none law. (In skeletal muscle only a single fibre obeys it.) Staircase is attributed to increased availability of intracellular Ca²⁺ with successive beats (and possibly a rise in temperature/lowered viscosity).", "prec": ["Use single break shocks.", "Allow sufficient interval between stimuli for all-or-none.", "Keep the stimulus strength constant for staircase.", "Keep the heart moist."], "viva": [["Why does the whole ventricle obey the all-or-none law?", "It is a functional syncytium – gap junctions allow the impulse to spread to all fibres."], ["Does whole skeletal muscle obey the all-or-none law?", "No; only a single skeletal muscle fibre (or motor unit) does; whole muscle response grades with recruitment."], ["What is the staircase phenomenon?", "Progressive increase in force of the first few contractions when quiescent muscle is stimulated repeatedly at constant strength; due to increased Ca²⁺ availability."], ["Why is a Stannius ligature used here?", "To obtain a quiescent ventricle so that responses are only to the applied stimuli."]], "cal": "CBME note: live frog experiments are no longer done; these are taught with computer simulations, computer-assisted learning (CAL) modules or recorded demonstrations. Learn the tracings and their explanation."}}], ["Refractory period, extrasystole and compensatory pause", "Aim: To demonstrate the refractory period of cardiac muscle, and to record extrasystole and compensatory pause in the frog heart.", "", ["Why is the heart not tetanized?", "What is a compensatory pause?", "Why is an extrasystole smaller?", "Where should the stimulus be applied to get an extrasystole?"], {"kp": ["ARP = whole of systole → no tetanus.", "Stimulus in diastole → extrasystole + compensatory pause."], "ex": "Viva/practical record: Aim → apparatus → procedure → tracing (labelled) → observations → explanation → precautions.", "ae": {"aim": "To demonstrate the refractory period of cardiac muscle, and to record extrasystole and compensatory pause in the frog heart.", "app": ["As for normal cardiogram", "Induction coil, key, electrodes placed on the ventricle", "Drum at moderate speed"], "steps": ["Record the normal cardiogram.", "Apply a single maximal break shock to the ventricle at different phases of the cardiac cycle: during systole, early diastole, and late diastole.", "Record the response and mark the instant of each stimulus."], "tr": "Stimulus during systole: the tracing is unchanged. Stimulus during diastole: an extra, premature beat (extrasystole) appears, usually smaller, followed by a longer than normal pause (compensatory pause) before the next normal beat.", "obs": ["Stimulus during systole (and the very beginning of diastole) – no response: absolute refractory period.", "Stimulus during diastole – extrasystole (premature ventricular beat).", "The extrasystole is followed by a compensatory pause.", "Extrasystole given later in diastole is larger than one given earlier (relative refractory period)."], "expl": "The absolute refractory period of cardiac muscle lasts throughout systole, so the heart cannot respond during systole and cannot be tetanized. A stimulus in diastole produces a premature ventricular contraction. The next normal impulse from the sinus venosus reaches the ventricle while it is still refractory from the extrasystole, so it is ineffective; the ventricle waits for the following impulse – hence the compensatory pause.", "prec": ["Stimulate only once per cycle.", "Electrodes must touch the ventricle lightly without obstructing its movement.", "Mark the exact time of stimulus."], "viva": [["Why is the heart not tetanized?", "Its absolute refractory period extends through the whole of systole."], ["What is a compensatory pause?", "The longer pause after an extrasystole because the next sinus impulse reaches the ventricle in its refractory period, so the ventricle waits for the following impulse."], ["Why is an extrasystole smaller?", "It occurs before the ventricle has fully recovered and filled (relative refractory period / less time for filling)."], ["Where should the stimulus be applied to get an extrasystole?", "On the ventricle, during diastole."]], "cal": "CBME note: live frog experiments are no longer done; these are taught with computer simulations, computer-assisted learning (CAL) modules or recorded demonstrations. Learn the tracings and their explanation."}}], ["Stannius ligatures", "Aim: To study the origin and conduction of the heartbeat (pacemaker hierarchy) in the frog heart using Stannius ligatures.", "", ["What does the first Stannius ligature show?", "Why does the ventricle restart after the second ligature?", "Does the apex beat spontaneously?", "What is the mammalian equivalent of the sinus venosus?"], {"kp": ["1st: SV–atrial junction → atria & ventricle stop.", "2nd: AV junction → ventricle restarts (slower).", "3rd: apex – no spontaneous beat, still excitable.", "Hierarchy: sinus venosus > atria > AV junction."], "ex": "Viva/practical record: Aim → apparatus → procedure → tracing (labelled) → observations → explanation → precautions.", "ae": {"aim": "To study the origin and conduction of the heartbeat (pacemaker hierarchy) in the frog heart using Stannius ligatures.", "app": ["As for normal cardiogram", "Fine thread for ligatures", "Optional induction coil to stimulate the apex"], "steps": ["Record the normal cardiogram and note the rates of sinus venosus, atria and ventricle.", "First ligature: tie a thread at the junction of the sinus venosus and the right atrium (sino-atrial junction). Observe and record.", "Second ligature: tie a thread at the atrioventricular junction. Observe and record.", "Third ligature: tie a thread across the lower part of the ventricle to isolate the apex. Observe; stimulate the apex if needed."], "tr": "After the first ligature the ventricular tracing becomes a flat line (sinus venosus continues to beat, visible to the eye). After the second ligature the ventricular tracing resumes with beats at a slower rate than normal. After the third ligature, the isolated apex gives no tracing unless stimulated.", "obs": ["1st ligature: sinus venosus continues beating at its own rate; atria and ventricle stop. After some time they may start beating at a slower rhythm.", "2nd ligature: ventricle starts beating again (at a slower rate), atria remain stopped or beat at their own slow rate.", "3rd ligature: the apex does not beat spontaneously but contracts when stimulated."], "expl": "The sinus venosus has the highest rhythmicity and acts as the pacemaker. After the 1st ligature, impulses cannot pass from the sinus venosus to the atria, so the atria and ventricle stop until a lower pacemaker takes over. The 2nd ligature mechanically stimulates the specialised tissue at the atrioventricular junction, which then beats at its own slower rate. The apex has no inherent rhythmicity but remains excitable and contractile. This shows the hierarchy: sinus venosus > atria > AV junction > (apex: none).", "prec": ["Tie ligatures at the exact junctions.", "Tie firmly enough to block conduction, but do not cut through the tissue.", "Keep the heart moist."], "viva": [["What does the first Stannius ligature show?", "The beat originates in the sinus venosus; atria and ventricle stop because impulses cannot reach them."], ["Why does the ventricle restart after the second ligature?", "Mechanical stimulation of the specialised AV junctional tissue, which has its own (slower) rhythm."], ["Does the apex beat spontaneously?", "No – it has no rhythmicity, but it is excitable and contracts when stimulated."], ["What is the mammalian equivalent of the sinus venosus?", "The SA node, which develops from the sinus venosus region."]], "cal": "CBME note: live frog experiments are no longer done; these are taught with computer simulations, computer-assisted learning (CAL) modules or recorded demonstrations. Learn the tracings and their explanation."}}], ["Effect of temperature on the frog heart", "Aim: To study the effect of warm and cold Ringer's solution on the frog heart.", "", ["What is the effect of warmth on heart rate?", "Why is the effect marked over the sinus venosus?", "Clinical correlation?"], {"kp": ["Warm → ↑ rate; cold → ↓ rate.", "Most marked at sinus venosus."], "ex": "Viva/practical record: Aim → apparatus → procedure → tracing (labelled) → observations → explanation → precautions.", "ae": {"aim": "To study the effect of warm and cold Ringer's solution on the frog heart.", "app": ["As for normal cardiogram", "Ringer's solution at room temperature, warm (about 30–35 °C) and cold"], "steps": ["Record the normal cardiogram.", "Pour cold Ringer's solution over the heart (sinus venosus region) and record.", "Allow recovery to normal, then pour warm Ringer's solution and record.", "Count the rate in each condition against the time trace."], "tr": "Cold: beats are spaced widely (slower rate). Warm: beats are crowded together (faster rate).", "obs": ["Warm Ringer's – heart rate increases (positive chronotropic effect).", "Cold Ringer's – heart rate decreases (negative chronotropic effect).", "The effect is most marked when the solution is applied to the sinus venosus (pacemaker).", "Changes in height of contraction are smaller and less consistent than changes in rate."], "expl": "Temperature alters the rate of the metabolic and ionic processes that produce the pacemaker potential in the sinus venosus; warmth speeds diastolic depolarisation and so increases the rate, cold slows it.", "prec": ["Use moderate temperatures; very hot solution damages the heart.", "Allow the heart to return to normal before the next application.", "Apply to the sinus venosus region."], "viva": [["What is the effect of warmth on heart rate?", "Increases rate (positive chronotropic)."], ["Why is the effect marked over the sinus venosus?", "It is the pacemaker; temperature changes the rate of its pacemaker potential."], ["Clinical correlation?", "Fever increases heart rate; hypothermia causes bradycardia."]], "cal": "CBME note: live frog experiments are no longer done; these are taught with computer simulations, computer-assisted learning (CAL) modules or recorded demonstrations. Learn the tracings and their explanation."}}], ["Vagal stimulation and vagal escape", "Aim: To study the effect of stimulating the vagus (vago-sympathetic trunk) on the frog heart and to demonstrate vagal escape.", "", ["What is vagal escape?", "What are the possible causes of vagal escape?", "Why is it called the vago-sympathetic trunk in the frog?", "How does acetylcholine slow the heart?", "What is the white crescentic line?"], {"kp": ["Faradic stimulation of vago-sympathetic trunk → ↓ rate & force, diastolic arrest.", "Vagal escape despite continued stimulation.", "Post-stimulation acceleration (sympathetic fibres)."], "ex": "Viva/practical record: Aim → apparatus → procedure → tracing (labelled) → observations → explanation → precautions.", "ae": {"aim": "To study the effect of stimulating the vagus (vago-sympathetic trunk) on the frog heart and to demonstrate vagal escape.", "app": ["As for normal cardiogram", "Induction coil with Neef's hammer (faradic current) or electronic stimulator", "Fine electrodes; glass hook"], "steps": ["Expose the heart and record the normal cardiogram.", "Identify and isolate the vago-sympathetic trunk in the neck region (it accompanies the jugular vein / lies near the petrohyoid muscles) and place it on the electrodes.", "Stimulate with a faradic (repetitive) current for a prolonged period and mark the duration of stimulation.", "Continue stimulation until the heart resumes beating; then stop and record the recovery."], "tr": "After a short latent period from the start of stimulation the beats become slower and weaker and the tracing becomes a flat diastolic line. Despite continued stimulation the beats reappear, gradually reaching nearly the original rate and size. After stimulation stops the beats may be faster and stronger for a while.", "obs": ["Latent period before the effect begins.", "Decrease in rate and force; heart may stop in diastole (vagal inhibition).", "Vagal escape: the heart starts beating again in spite of continued stimulation.", "Post-stimulation acceleration may occur after stimulation stops, because the frog vagus is a mixed vago-sympathetic trunk carrying sympathetic fibres."], "expl": "Vagal fibres release acetylcholine, which acts on muscarinic receptors of the pacemaker (sinus venosus) and atria: it increases K⁺ conductance and hyperpolarises the cells, decreasing the rate and force of contraction. Vagal escape is explained by several suggested mechanisms – e.g. emergence of a latent pacemaker, depletion of acetylcholine, and the effect of sympathetic fibres in the vago-sympathetic trunk; the exact mechanism is uncertain. Stimulating the white crescentic line (the sino-atrial junction) produces similar inhibitory effects through intracardiac vagal fibres.", "prec": ["Isolate the nerve gently with a glass hook; do not stretch or crush it.", "Keep electrodes from touching the heart.", "Use a moderate faradic current and mark the period of stimulation.", "Allow recovery between stimulations."], "viva": [["What is vagal escape?", "Resumption of heartbeat despite continued vagal stimulation."], ["What are the possible causes of vagal escape?", "Latent pacemaker taking over, depletion of acetylcholine, and effect of sympathetic fibres in the vago-sympathetic trunk; mechanism not fully settled."], ["Why is it called the vago-sympathetic trunk in the frog?", "Sympathetic fibres join the vagus, so stimulation may also produce a sympathetic (accelerating) effect."], ["How does acetylcholine slow the heart?", "By acting on M2 muscarinic receptors to open K⁺ channels, hyperpolarising the pacemaker and slowing its depolarisation."], ["What is the white crescentic line?", "The line at the junction of the sinus venosus and right atrium; stimulating it produces vagal-like inhibition."]], "cal": "CBME note: live frog experiments are no longer done; these are taught with computer simulations, computer-assisted learning (CAL) modules or recorded demonstrations. Learn the tracings and their explanation."}}], ["Effects of drugs and ions on the frog heart", "Aim: To study the effects of adrenaline, acetylcholine, atropine, calcium and potassium on the frog heart.", "", ["In which phase does excess K⁺ stop the heart?", "In which phase does excess Ca²⁺ stop the heart?", "How does atropine act?", "Clinical importance of K⁺ arrest?", "Effect of adrenaline?"], {"kp": ["Adrenaline ↑ rate & force; ACh ↓ (diastolic arrest).", "Atropine blocks ACh/vagus.", "Excess Ca²⁺ → systolic arrest (Ca rigor); excess K⁺ → diastolic arrest."], "ex": "Viva/practical record: Aim → apparatus → procedure → tracing (labelled) → observations → explanation → precautions.", "ae": {"aim": "To study the effects of adrenaline, acetylcholine, atropine, calcium and potassium on the frog heart.", "app": ["As for normal cardiogram", "Ringer's solution; dilute solutions of adrenaline, acetylcholine, atropine, CaCl₂ and KCl", "Dropper / pipette"], "steps": ["Record the normal cardiogram.", "Apply a few drops of the test solution on the heart (or add to the perfusion fluid); record the effect.", "Wash the heart with Ringer's solution and allow it to return to normal before the next drug.", "For atropine: apply acetylcholine, observe the effect, then apply atropine; or apply atropine first and then show that acetylcholine (or vagal stimulation) is ineffective."], "tr": "Adrenaline: beats crowded and taller. Acetylcholine: beats spaced out and smaller, may become a flat line at the diastolic level. Atropine then ACh: tracing stays normal. Excess Ca²⁺: taller beats with prolonged systole; the tracing finally stays at the systolic (top) level. Excess K⁺: smaller and slower beats ending as a flat line at the diastolic (baseline) level.", "obs": ["Adrenaline – increased rate and force (positive chronotropic and inotropic).", "Acetylcholine – decreased rate and force; arrest in diastole.", "Atropine – blocks the action of acetylcholine and of vagal stimulation; by itself little change in the isolated frog heart.", "Excess Ca²⁺ – increased force, prolonged systole, finally arrest in systole (calcium rigor).", "Excess K⁺ – decreased rate, force and excitability; arrest in diastole."], "expl": "Adrenaline acts on β-adrenergic receptors to increase Ca²⁺ entry and pacemaker rate. Acetylcholine acts on muscarinic receptors (opening K⁺ channels, hyperpolarisation). Atropine is a competitive muscarinic antagonist. Ca²⁺ is essential for excitation–contraction coupling; excess keeps the muscle contracted. Raised extracellular K⁺ reduces the membrane potential and inactivates Na⁺ channels, decreasing excitability and conduction, so the heart stops in diastole (the basis of cardioplegic solutions).", "prec": ["Use dilute solutions and a few drops only.", "Wash with Ringer's solution and allow recovery between drugs.", "Label each tracing with the drug used."], "viva": [["In which phase does excess K⁺ stop the heart?", "Diastole."], ["In which phase does excess Ca²⁺ stop the heart?", "Systole (calcium rigor)."], ["How does atropine act?", "Competitive blocker of muscarinic receptors; prevents the effects of ACh and vagal stimulation."], ["Clinical importance of K⁺ arrest?", "Cardioplegic solutions rich in K⁺ are used to stop the heart in diastole during cardiac surgery; hyperkalaemia can cause cardiac arrest."], ["Effect of adrenaline?", "Increases rate and force via β1 receptors."]], "cal": "CBME note: live frog experiments are no longer done; these are taught with computer simulations, computer-assisted learning (CAL) modules or recorded demonstrations. Learn the tracings and their explanation."}}], ["Perfusion of the isolated frog heart", "Aim: To perfuse the isolated frog heart with Ringer's solution and study the effects of ions and drugs added to the perfusate.", "", ["What does the perfusion experiment prove?", "What is the concentration of NaCl in frog Ringer's?", "What happens with Ca²⁺-free perfusion?", "What cannula is used?"], {"kp": ["Symes' cannula; frog Ringer's (0.65% NaCl).", "Heartbeat myogenic; Ca²⁺ essential.", "Ca²⁺ excess – systolic arrest; K⁺ excess – diastolic arrest."], "ex": "Viva/practical record: Aim → apparatus → procedure → tracing (labelled) → observations → explanation → precautions.", "ae": {"aim": "To perfuse the isolated frog heart with Ringer's solution and study the effects of ions and drugs added to the perfusate.", "app": ["Symes' perfusion cannula with a reservoir (Mariotte bottle) of Ringer's solution", "Starling's heart lever, kymograph", "Frog Ringer's solution and test solutions"], "steps": ["Pith the frog and expose the heart.", "Tie the perfusion cannula into the heart through the venous inflow (via the sinus venosus) so that Ringer's solution flows through the chambers; cut the aortae so that fluid leaves freely.", "Remove the heart from the body with the cannula and mount it on a stand; attach the apex to the heart lever.", "Perfuse with normal Ringer's at a constant pressure and record the normal cardiogram.", "Change the perfusion fluid to one containing the test substance (e.g. excess K⁺, excess Ca²⁺, Ca²⁺-free, adrenaline, acetylcholine) and record; return to normal Ringer's between tests."], "tr": "Normal Ringer's: regular beats. Ca²⁺-free fluid: beats become progressively weaker until the heart stops (in diastole). Excess Ca²⁺: stronger beats, then systolic arrest. Excess K⁺: weaker, slower beats, then diastolic arrest. Drugs give the same effects as on the in-situ heart.", "obs": ["The isolated heart continues to beat when perfused with Ringer's solution – showing that the heartbeat is myogenic (originates in the heart itself).", "Ca²⁺ is essential for contraction: without Ca²⁺ the beats weaken and stop.", "Excess Ca²⁺ → systolic arrest; excess K⁺ → diastolic arrest.", "A balance of Na⁺, K⁺ and Ca²⁺ is needed for normal beating."], "expl": "Sydney Ringer (1880s) found that the isolated frog heart beat well only when the saline contained Ca²⁺ and K⁺ in addition to NaCl; Ca²⁺ is required for excitation–contraction coupling. Frog Ringer's solution contains about 0.65% NaCl (isotonic for amphibians) with small amounts of KCl, CaCl₂ and NaHCO₃.", "prec": ["Avoid air bubbles in the cannula and tubing.", "Maintain constant perfusion pressure and temperature.", "Do not tie the sinus venosus tightly enough to damage it.", "Wash out with normal Ringer's between tests."], "viva": [["What does the perfusion experiment prove?", "That the heartbeat is myogenic and that a proper balance of ions (Na⁺, K⁺, Ca²⁺) is needed."], ["What is the concentration of NaCl in frog Ringer's?", "About 0.65% (isotonic for amphibian tissues), compared with 0.9% for mammals."], ["What happens with Ca²⁺-free perfusion?", "Contractions weaken and the heart stops, because Ca²⁺ is needed for excitation–contraction coupling."], ["What cannula is used?", "Symes' perfusion cannula."]], "cal": "CBME note: live frog experiments are no longer done; these are taught with computer simulations, computer-assisted learning (CAL) modules or recorded demonstrations. Learn the tracings and their explanation."}}], ["Simulations and CAL in CBME (replacing live animals)", "Aim: To understand why and how amphibian experiments are now taught by computer simulations under the NMC CBME curriculum.", "", ["Why are animal experiments replaced by simulations?", "What are the 3 Rs?"], {"kp": ["CBME: frog experiments taught by simulation/CAL.", "3 Rs: Replacement, Reduction, Refinement."], "ex": "Viva/practical record: Aim → apparatus → procedure → tracing (labelled) → observations → explanation → precautions.", "ae": {"aim": "To understand why and how amphibian experiments are now taught by computer simulations under the NMC CBME curriculum.", "app": ["Computer or tablet with simulation software (virtual physiology labs simulating nerve–muscle and frog heart experiments)", "Recorded videos of demonstrations", "Digital data-acquisition systems used on human volunteers (e.g. ergography, EMG, ECG)"], "steps": ["Select the simulated experiment (e.g. simple muscle twitch, tetanus, frog heart).", "Set the variables (stimulus strength, frequency, load, temperature, drug).", "Run the simulation and save/print the tracing.", "Label the tracing, measure periods and write observations and explanation as in the classical experiment.", "Answer viva questions on the underlying physiology."], "tr": "Simulated tracings reproduce the classical kymograph records (twitch, summation, tetanus, fatigue, cardiogram, Stannius, drug effects).", "obs": ["Same learning outcomes as the live experiments without using animals.", "Allows repetition and changing one variable at a time."], "expl": "Use of animals for undergraduate teaching was discontinued in India following regulations restricting animal experiments for education, and the CBME curriculum recommends computer-assisted learning/simulation for these experiments. The 3 Rs of animal ethics – Replacement, Reduction, Refinement – guide this change.", "prec": ["Treat simulations as real experiments: record, label, interpret.", "Know the classical apparatus and tracings – they are still asked in viva."], "viva": [["Why are animal experiments replaced by simulations?", "For ethical reasons (3 Rs – Replacement, Reduction, Refinement) and following regulations restricting animal use for teaching; CBME recommends CAL/simulation."], ["What are the 3 Rs?", "Replacement, Reduction and Refinement of animal use."]], "cal": "CBME note: live frog experiments are no longer done; these are taught with computer simulations, computer-assisted learning (CAL) modules or recorded demonstrations. Learn the tracings and their explanation."}}]], "fc": [["Periods of simple muscle twitch (frog)", "Latent ≈0.01 s, contraction ≈0.04 s, relaxation ≈0.05 s; total ≈0.1 s.", "Simple muscle twitch (gastrocnemius–sciatic preparation)"], ["Free-load vs after-load", "Free-load pre-stretches muscle → more work; after-load keeps initial length constant.", "Effect of load: free-load and after-load (work done)"], ["Complete vs incomplete tetanus", "Complete: stimuli fall in contraction phase (smooth); incomplete/clonus: in relaxation phase (wavy).", "Genesis of tetanus"], ["Compensatory pause", "Next sinus impulse falls in ARP of the extrasystole → ventricle waits for the following impulse.", "Refractory period, extrasystole and compensatory pause"], ["Stannius ligatures", "1st SA junction – A & V stop; 2nd AV junction – V restarts slowly; 3rd apex – no spontaneous beat.", "Stannius ligatures"], ["Vagal escape", "Heart resumes beating despite continued vagal stimulation (latent pacemaker, ACh depletion, sympathetic fibres).", "Vagal stimulation and vagal escape"], ["Ca²⁺ vs K⁺ excess on heart", "Ca²⁺ → arrest in systole (calcium rigor); K⁺ → arrest in diastole.", "Effects of drugs and ions on the frog heart"]], "mcq": [{"q": "In the induction coil, the break shock is stronger than the make shock because", "o": ["Of self-induction at make", "The secondary coil is moved", "The battery voltage rises", "Of fatigue of the electrodes"], "a": 0, "e": "Self-induction opposes the build-up of current at make; at break the current falls abruptly, so the induced current is stronger.", "t": "Apparatus for amphibian experiments", "src": "text", "id": "ae-a629969a6b"}, {"q": "Neef's hammer is used to obtain", "o": ["A single break shock", "A faradic (tetanizing) current", "A galvanic (constant) current", "A time trace"], "a": 1, "e": "It automatically interrupts the primary circuit repeatedly, giving repetitive shocks.", "t": "Apparatus for amphibian experiments", "src": "text", "id": "ae-c37367175f"}, {"q": "A tuning fork vibrating at 100 Hz records each wave as", "o": ["0.1 s", "0.01 s", "0.001 s", "1 s"], "a": 1, "e": "1/100 s = 0.01 s per vibration.", "t": "Apparatus for amphibian experiments", "src": "text", "id": "ae-9bb46135c3"}, {"q": "In a simple muscle twitch of frog gastrocnemius, the latent period is about", "o": ["0.001 s", "0.01 s", "0.04 s", "0.1 s"], "a": 1, "e": "Latent period ≈ 0.01 s; contraction ≈ 0.04 s; relaxation ≈ 0.05 s.", "t": "Simple muscle twitch (gastrocnemius–sciatic preparation)", "src": "text", "id": "ae-839d65aefa"}, {"q": "The longest period of a simple muscle twitch is", "o": ["Latent period", "Contraction period", "Relaxation period", "Refractory period"], "a": 2, "e": "Relaxation (≈0.05 s) is longer than contraction (≈0.04 s).", "t": "Simple muscle twitch (gastrocnemius–sciatic preparation)", "src": "text", "id": "ae-ac7e423a88"}, {"q": "Which is NOT a component of the latent period recorded on a kymograph?", "o": ["Excitation–contraction coupling", "Inertia of the lever", "Neuromuscular transmission", "Cross-bridge detachment during relaxation"], "a": 3, "e": "Cross-bridge detachment occurs during relaxation, after the latent period.", "t": "Simple muscle twitch (gastrocnemius–sciatic preparation)", "src": "text", "id": "ae-7a8303297b"}, {"q": "A simple muscle twitch of frog gastrocnemius lasts about", "o": ["0.01 s", "0.1 s", "1 s", "0.5 s"], "a": 1, "e": "Total duration ≈ 0.1 s at room temperature.", "t": "Simple muscle twitch (gastrocnemius–sciatic preparation)", "src": "text", "id": "ae-eac5ed3303"}, {"q": "Warm Ringer's solution applied to a frog muscle causes", "o": ["Prolonged latent period", "Shortened periods of the twitch", "No change", "Decreased height and prolonged relaxation"], "a": 1, "e": "Warmth speeds chemical reactions and reduces viscosity → all periods shorten.", "t": "Effect of temperature on muscle twitch", "src": "text", "id": "ae-ce68d8f594"}, {"q": "Heat rigor is due to", "o": ["Lack of ATP", "Coagulation of muscle proteins", "Excess acetylcholine", "Fatigue of the nerve"], "a": 1, "e": "Heat rigor is irreversible coagulation of proteins.", "t": "Effect of temperature on muscle twitch", "src": "text", "id": "ae-524ee3bb82"}, {"q": "Cold Ringer's solution", "o": ["Shortens all periods", "Prolongs all periods", "Abolishes the latent period", "Produces tetanus"], "a": 1, "e": "Cold slows reactions and increases viscosity.", "t": "Effect of temperature on muscle twitch", "src": "text", "id": "ae-ca774ea7c9"}, {"q": "In an after-loaded muscle, as the load increases the height of contraction", "o": ["Increases continuously", "First increases then decreases", "Decreases progressively", "Remains constant"], "a": 2, "e": "Initial length is not increased, so height falls progressively.", "t": "Effect of load: free-load and after-load (work done)", "src": "text", "id": "ae-bd7a021bc7"}, {"q": "Work done by a muscle is maximal", "o": ["With no load", "With the maximum load", "At an intermediate (optimum) load", "Only in after-load"], "a": 2, "e": "Work = load × distance; zero at both extremes.", "t": "Effect of load: free-load and after-load (work done)", "src": "text", "id": "ae-b6e38ad248"}, {"q": "The greater work done in free-loading is explained by", "o": ["Increased initial length", "Fatigue", "Heat rigor", "Summation"], "a": 0, "e": "Pre-stretch improves the length–tension relationship.", "t": "Effect of load: free-load and after-load (work done)", "src": "text", "id": "ae-52e8b1f5a0"}, {"q": "If the second stimulus falls within the refractory period of skeletal muscle", "o": ["Tetanus occurs", "A taller contraction occurs", "No additional response occurs", "The muscle relaxes"], "a": 2, "e": "A tissue cannot be re-excited in the absolute refractory period.", "t": "Effect of two successive stimuli (summation)", "src": "text", "id": "ae-0afa44d81f"}, {"q": "Summation of contractions is possible in skeletal muscle because", "o": ["Its refractory period is short compared with its contraction", "It has pacemaker cells", "It has gap junctions", "It lacks sarcoplasmic reticulum"], "a": 0, "e": "The refractory period ends well before the mechanical response.", "t": "Effect of two successive stimuli (summation)", "src": "text", "id": "ae-5d4389605c"}, {"q": "Two stimuli given after complete relaxation produce", "o": ["One fused contraction", "Two separate twitches", "No response", "Tetanus"], "a": 1, "e": "Each stimulus gives its own twitch; the second may be slightly taller (beneficial effect).", "t": "Effect of two successive stimuli (summation)", "src": "text", "id": "ae-f4351aa063"}, {"q": "Complete tetanus occurs when successive stimuli fall in the", "o": ["Latent period", "Contraction period", "Relaxation period", "After complete relaxation"], "a": 1, "e": "Stimuli during contraction give a smooth fused response.", "t": "Genesis of tetanus", "src": "text", "id": "ae-bd039eab71"}, {"q": "Cardiac muscle cannot be tetanized because", "o": ["It has a long absolute refractory period", "It lacks T tubules", "It has no troponin", "It is not excitable"], "a": 0, "e": "The ARP lasts throughout systole.", "t": "Genesis of tetanus", "src": "text", "id": "ae-f5b018822f"}, {"q": "Clonus (incomplete tetanus) shows", "o": ["A smooth plateau", "A wavy plateau with partial relaxation", "No contraction", "A single twitch"], "a": 1, "e": "Stimuli fall during relaxation of the previous contraction.", "t": "Genesis of tetanus", "src": "text", "id": "ae-318305950d"}, {"q": "In a nerve–muscle preparation, the first site of fatigue is the", "o": ["Nerve trunk", "Neuromuscular junction", "Muscle fibre", "Electrode"], "a": 1, "e": "Direct stimulation still elicits contraction after indirect stimulation fails.", "t": "Fatigue in skeletal muscle", "src": "text", "id": "ae-c9524e9459"}, {"q": "In a fatigued muscle, the period most prolonged is", "o": ["Latent period", "Contraction period", "Relaxation period", "None"], "a": 2, "e": "Relaxation is prolonged most; incomplete relaxation causes contracture.", "t": "Fatigue in skeletal muscle", "src": "text", "id": "ae-2e385b6495"}, {"q": "The nerve fibre is", "o": ["Easily fatigued", "Practically unfatigable", "Fatigued before the NMJ", "Not excitable"], "a": 1, "e": "Nerve is practically unfatigable.", "t": "Fatigue in skeletal muscle", "src": "text", "id": "ae-c99e9e79eb"}, {"q": "Velocity of nerve impulse in this experiment is calculated as", "o": ["Distance ÷ total latent period", "Distance between stimulation points ÷ difference in latent periods", "Height ÷ time", "Load × height"], "a": 1, "e": "Other components of the latent period cancel out.", "t": "Velocity of nerve impulse (frog sciatic nerve)", "src": "text", "id": "ae-fb6e0ab067"}, {"q": "Conduction velocity in frog sciatic nerve at room temperature is roughly", "o": ["0.5 m/s", "30 m/s", "120 m/s", "300 m/s"], "a": 1, "e": "About 30 m/s (Helmholtz measured ~27 m/s).", "t": "Velocity of nerve impulse (frog sciatic nerve)", "src": "text", "id": "ae-6904ff4ee8"}, {"q": "Conduction velocity increases with", "o": ["Decrease in temperature", "Smaller fibre diameter", "Myelination", "Fatigue"], "a": 2, "e": "Saltatory conduction in myelinated fibres is faster.", "t": "Velocity of nerve impulse (frog sciatic nerve)", "src": "text", "id": "ae-65e663db7a"}, {"q": "The pacemaker of the frog heart is the", "o": ["SA node", "Sinus venosus", "Ventricle", "Truncus arteriosus"], "a": 1, "e": "In the frog the beat originates in the sinus venosus.", "t": "Normal cardiogram of the frog heart", "src": "text", "id": "ae-cacc94a8e0"}, {"q": "In the frog cardiogram, the small wave preceding the main wave is due to", "o": ["Ventricular systole", "Atrial systole", "Diastole", "Truncus contraction"], "a": 1, "e": "Atrial systole precedes ventricular systole.", "t": "Normal cardiogram of the frog heart", "src": "text", "id": "ae-dd752a0b04"}, {"q": "The frog heart has", "o": ["Two atria and two ventricles", "Two atria and one ventricle", "One atrium and one ventricle", "One atrium and two ventricles"], "a": 1, "e": "Three-chambered heart.", "t": "Normal cardiogram of the frog heart", "src": "text", "id": "ae-1e59fc3d70"}, {"q": "The whole cardiac ventricle obeys the all-or-none law because it", "o": ["Has a long refractory period", "Is a functional syncytium", "Has pacemaker cells", "Has no T tubules"], "a": 1, "e": "Gap junctions spread excitation to all fibres.", "t": "All-or-none law and staircase phenomenon (frog heart)", "src": "text", "id": "ae-d8dcf69aed"}, {"q": "Staircase (Treppe) phenomenon is attributed to", "o": ["Increased Ca²⁺ availability", "Fatigue", "Depletion of ACh", "Vagal escape"], "a": 0, "e": "Successive beats increase intracellular Ca²⁺.", "t": "All-or-none law and staircase phenomenon (frog heart)", "src": "text", "id": "ae-002b00d7a1"}, {"q": "In the all-or-none experiment on the frog ventricle, a stimulus twice the threshold produces", "o": ["A contraction twice as strong", "The same maximal contraction", "Tetanus", "No response"], "a": 1, "e": "Above threshold, the response is maximal and does not grade.", "t": "All-or-none law and staircase phenomenon (frog heart)", "src": "text", "id": "ae-69792a65d8"}, {"q": "A stimulus applied to the frog ventricle during systole produces", "o": ["Extrasystole", "Tetanus", "No response", "Compensatory pause only"], "a": 2, "e": "Systole falls in the absolute refractory period.", "t": "Refractory period, extrasystole and compensatory pause", "src": "text", "id": "ae-9a26e06530"}, {"q": "The compensatory pause after an extrasystole is due to", "o": ["Vagal stimulation", "The next sinus impulse falling in the refractory period of the extrasystole", "Fatigue", "Calcium rigor"], "a": 1, "e": "The next normal impulse is ineffective, so the ventricle waits for the following one.", "t": "Refractory period, extrasystole and compensatory pause", "src": "text", "id": "ae-7f3a8ef21b"}, {"q": "The absolute refractory period of cardiac muscle lasts", "o": ["Only the latent period", "Throughout systole", "Throughout diastole", "0.005 s"], "a": 1, "e": "This prevents tetanus of the heart.", "t": "Refractory period, extrasystole and compensatory pause", "src": "text", "id": "ae-59e7bc8103"}, {"q": "After the first Stannius ligature", "o": ["The sinus venosus stops", "The atria and ventricle stop while the sinus venosus continues", "Only the ventricle beats", "The heart fibrillates"], "a": 1, "e": "Conduction from the pacemaker to the atria is blocked.", "t": "Stannius ligatures", "src": "text", "id": "ae-5ea65e3f83"}, {"q": "The second Stannius ligature is tied at the", "o": ["Sino-atrial junction", "Atrioventricular junction", "Apex", "Truncus arteriosus"], "a": 1, "e": "It stimulates the AV junctional tissue, which restarts the ventricle.", "t": "Stannius ligatures", "src": "text", "id": "ae-caca50445a"}, {"q": "The isolated apex of the frog ventricle", "o": ["Beats spontaneously faster", "Does not beat spontaneously but contracts on stimulation", "Is not excitable", "Shows tetanus"], "a": 1, "e": "The apex lacks rhythmicity but retains excitability and contractility.", "t": "Stannius ligatures", "src": "text", "id": "ae-efa33442ef"}, {"q": "Stannius ligatures demonstrate", "o": ["All-or-none law", "The pacemaker hierarchy of the heart", "Vagal escape", "Staircase"], "a": 1, "e": "Origin and conduction of the heartbeat.", "t": "Stannius ligatures", "src": "text", "id": "ae-84d72cd3e6"}, {"q": "Warm Ringer's applied to the sinus venosus of a frog heart", "o": ["Decreases heart rate", "Increases heart rate", "Stops the heart in systole", "Has no effect"], "a": 1, "e": "Warmth speeds pacemaker depolarisation.", "t": "Effect of temperature on the frog heart", "src": "text", "id": "ae-2822188c2d"}, {"q": "Cold Ringer's solution on the frog heart produces", "o": ["Tachycardia", "Bradycardia", "Tetanus", "Calcium rigor"], "a": 1, "e": "Pacemaker activity is slowed.", "t": "Effect of temperature on the frog heart", "src": "text", "id": "ae-1cd79fc8de"}, {"q": "Resumption of heartbeat despite continuous vagal stimulation is called", "o": ["Staircase", "Vagal escape", "Compensatory pause", "Extrasystole"], "a": 1, "e": "Vagal escape.", "t": "Vagal stimulation and vagal escape", "src": "text", "id": "ae-c6105f8a15"}, {"q": "Vagal stimulation of the frog heart causes arrest in", "o": ["Systole", "Diastole", "Tetanus", "Rigor"], "a": 1, "e": "ACh reduces rate and force; the heart stops in diastole.", "t": "Vagal stimulation and vagal escape", "src": "text", "id": "ae-18eab0f335"}, {"q": "Post-stimulation acceleration after frog vagal stimulation is due to", "o": ["Calcium rigor", "Sympathetic fibres in the vago-sympathetic trunk", "Atropine", "Fatigue"], "a": 1, "e": "The frog vagus is a mixed vago-sympathetic trunk.", "t": "Vagal stimulation and vagal escape", "src": "text", "id": "ae-0038cc8cdd"}, {"q": "Excess potassium in the perfusion fluid arrests the frog heart in", "o": ["Systole", "Diastole", "Tetanus", "Fibrillation"], "a": 1, "e": "High K⁺ reduces excitability; heart stops in diastole.", "t": "Effects of drugs and ions on the frog heart", "src": "text", "id": "ae-0807921294"}, {"q": "Calcium rigor refers to arrest of the heart in", "o": ["Diastole", "Systole", "Vagal escape", "Extrasystole"], "a": 1, "e": "Excess Ca²⁺ prolongs systole and finally stops the heart in systole.", "t": "Effects of drugs and ions on the frog heart", "src": "text", "id": "ae-8dd7f639cd"}, {"q": "Atropine abolishes the effect of", "o": ["Adrenaline", "Acetylcholine", "Calcium", "Warm Ringer's"], "a": 1, "e": "Atropine blocks muscarinic receptors.", "t": "Effects of drugs and ions on the frog heart", "src": "text", "id": "ae-6ff89ca747"}, {"q": "Adrenaline on the frog heart produces", "o": ["Decreased rate and force", "Increased rate and force", "Diastolic arrest", "No change"], "a": 1, "e": "Positive chronotropic and inotropic effects.", "t": "Effects of drugs and ions on the frog heart", "src": "text", "id": "ae-e2f3a376a1"}, {"q": "The NaCl concentration of frog Ringer's solution is about", "o": ["0.9%", "0.65%", "5%", "0.1%"], "a": 1, "e": "0.65% is isotonic for amphibian tissues.", "t": "Perfusion of the isolated frog heart", "src": "text", "id": "ae-8c5da54313"}, {"q": "Perfusing the frog heart with Ca²⁺-free Ringer's solution causes", "o": ["Systolic arrest", "Progressive weakening and stoppage of contractions", "Tetanus", "Increased force"], "a": 1, "e": "Ca²⁺ is essential for excitation–contraction coupling.", "t": "Perfusion of the isolated frog heart", "src": "text", "id": "ae-0d92e14b55"}, {"q": "The isolated perfused frog heart continues to beat, showing that the heartbeat is", "o": ["Neurogenic", "Myogenic", "Hormonal", "Reflex"], "a": 1, "e": "The beat originates in the heart itself.", "t": "Perfusion of the isolated frog heart", "src": "text", "id": "ae-bfd15bb1ed"}, {"q": "The 3 Rs of animal ethics are", "o": ["Repeat, Record, Report", "Replacement, Reduction, Refinement", "Rest, Relax, Recover", "Read, Revise, Recall"], "a": 1, "e": "Principles of humane animal research (Russell and Burch).", "t": "Simulations and CAL in CBME (replacing live animals)", "src": "text", "id": "ae-71353f763d"}], "imgs": [{"f": "ae_kymograph.webp", "ch": "Apparatus for amphibian experiments", "c": "Kymograph (recording drum) used by Sir Henry Dale, London, 1925–1935", "t": "Kymograph", "src": "File:Kymograph, London, England, 1925-1935 Wellcome L0057900.jpg", "url": "https://commons.wikimedia.org/wiki/File:Kymograph,_London,_England,_1925-1935_Wellcome_L0057900.jpg", "lic": "CC BY 4.0", "by": "Wellcome Collection"}, {"f": "ae_frog_heart_adrenaline.webp", "ch": "Effects of drugs and ions on the frog heart", "c": "Kymograph record of a frog heart: normal beats, then increasing doses of adrenaline (student project work)", "t": "Frog heart tracing – adrenaline", "src": "File:Frog heart kymographic recording.jpg", "url": "https://commons.wikimedia.org/wiki/File:Frog_heart_kymographic_recording.jpg", "lic": "CC BY-SA 4.0", "by": "Sachinthonakkara"}]};